:root { --ink:#1a1a24; --card:#f5f5dc; --accent:#e4572e; --highlight:#ffd23f; }
* { box-sizing: border-box; }
body { margin:0; min-height:100vh; display:flex; align-items:center; justify-content:center; background-color:#2b2b3a; background-image:linear-gradient(45deg,#3a3a4c 25%,transparent 25%),linear-gradient(-45deg,#3a3a4c 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#3a3a4c 75%),linear-gradient(-45deg,transparent 75%,#3a3a4c 75%); background-size:20px 20px; font-family:'Courier New',Courier,monospace; color:var(--ink); padding:16px; }
.pixel-card { background:var(--card); border:4px solid var(--ink); box-shadow:8px 8px 0 #000; padding:24px; width:min(420px,100%); image-rendering:pixelated; }
h1 { margin:0 0 20px; font-size:1.6rem; text-transform:uppercase; text-align:center; text-shadow:2px 2px 0 var(--highlight); }
.field { margin-bottom:16px; }
label { display:block; margin-bottom:6px; font-weight:bold; font-size:.95rem; }
input,select { width:100%; padding:10px; border:3px solid var(--ink); background:#fff; font:inherit; color:var(--ink); outline:none; box-shadow:3px 3px 0 #000; }
input:focus-visible,select:focus-visible,button:focus-visible { outline:3px dashed var(--accent); outline-offset:2px; }
button { display:block; width:100%; margin:20px 0 16px; padding:12px; border:3px solid var(--ink); background:var(--accent); color:#fff; font:inherit; font-weight:bold; text-transform:uppercase; letter-spacing:1px; cursor:pointer; box-shadow:4px 4px 0 #000; }
button:active { transform:translate(4px,4px); box-shadow:0 0 0 #000; }
.result { background:#fff; border:3px solid var(--ink); box-shadow:3px 3px 0 #000; padding:10px; font-size:1.3rem; display:flex; justify-content:space-between; align-items:center; gap:10px; }
.result-label { font-weight:bold; font-size:.9rem; }
#result { font-weight:bold; color:var(--accent); word-break:break-all; }
.formulas { margin:16px 0 0; font-size:.85rem; text-align:center; background:rgba(255,255,255,.5); padding:8px; border:2px dashed var(--ink); }

'use strict';
const temperatureInput = document.getElementById('temperature');
const directionSelect = document.getElementById('direction');
const convertButton = document.getElementById('convert');
const resultOutput = document.getElementById('result');
function convertTemperature() {
  const rawValue = temperatureInput.value.trim();
  if (rawValue === '') {
    resultOutput.textContent = 'Error';
    return;
  }
  const value = Number(rawValue);
  if (!Number.isFinite(value)) {
    resultOutput.textContent = 'Error';
    return;
  }
  const direction = directionSelect.value;
  let converted;
  if (direction === 'c-to-f') {
    converted = (value * 9) / 5 + 32;
  } else {
    converted = ((value - 32) * 5) / 9;
  }
  resultOutput.textContent = converted.toFixed(2);
}
convertButton.addEventListener('click', convertTemperature);
temperatureInput.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    convertTemperature();
  }
});
directionSelect.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    convertTemperature();
  }
});
